-- 0022 — Automatic, persisted general Examination access link + code.
-- Back-compatible: no exam, candidate, attempt, answer, score or result is
-- recreated. Existing invite tokens and access codes are preserved; missing
-- values are generated by the database, not by a browser.

-- Every exam gets a server-generated unique access code when the INSERT does
-- not supply one. The existing hash trigger still stores only the SHA-256
-- digest of the normalized code for shared-link verification.
create or replace function public.evalora_unique_exam_code()
returns text
language plpgsql
volatile
security definer
set search_path = public
as $$
declare candidate text;
begin
  loop
    candidate := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    exit when not exists (select 1 from public.exams where access_code = candidate);
  end loop;
  return candidate;
end $$;

grant execute on function public.evalora_unique_exam_code() to authenticated, service_role;
alter table public.exams alter column access_code set default public.evalora_unique_exam_code();

-- The persisted, exam-scoped link path is derived from the existing unique
-- invite token. Regenerating a token transparently regenerates this value.
alter table public.exams
  add column if not exists access_link text
  generated always as ('/exam/join/' || invite_token::text) stored;
create unique index if not exists uq_exams_access_link on public.exams(access_link);
comment on column public.exams.access_link is
  'Persisted candidate access path; prepend the deployment origin to form the shareable URL.';

-- Candidate identity extensions. First/last name, exam id, class, student id,
-- attempt id and timestamps already exist. Additional configured identity
-- fields are stored as a JSON object on both candidate and attempt.
alter table public.exam_candidates
  add column if not exists identity_data jsonb not null default '{}'::jsonb;
alter table public.exam_attempts
  add column if not exists identity_data jsonb not null default '{}'::jsonb;

alter table public.exam_candidates drop constraint if exists exam_candidates_identity_data_object;
alter table public.exam_candidates add constraint exam_candidates_identity_data_object
  check (jsonb_typeof(identity_data) = 'object');
alter table public.exam_attempts drop constraint if exists exam_attempts_identity_data_object;
alter table public.exam_attempts add constraint exam_attempts_identity_data_object
  check (jsonb_typeof(identity_data) = 'object');

-- Preserve any existing reference as identity data; never merge candidates
-- or student records by matching names.
update public.exam_candidates
set identity_data = jsonb_build_object('candidate_ref', candidate_ref)
where candidate_ref is not null and identity_data = '{}'::jsonb;

update public.exam_attempts a
set identity_data = c.identity_data
from public.exam_candidates c
where c.id = a.candidate_id
  and a.identity_data = '{}'::jsonb
  and c.identity_data <> '{}'::jsonb;

-- Add general access settings without overwriting Oak or legacy exam values.
update public.exams
set settings = coalesce(settings, '{}'::jsonb) || jsonb_build_object(
  'access_mode',
    case when settings->>'access_mode' = 'registered_students_only'
      then 'registered_students_only' else 'shared_link' end,
  'identity_fields',
    case when jsonb_typeof(settings->'identity_fields') = 'array'
      then settings->'identity_fields' else '[]'::jsonb end,
  'eligible_class_ids',
    case when jsonb_typeof(settings->'eligible_class_ids') = 'array'
      then settings->'eligible_class_ids' else '[]'::jsonb end,
  'attempt_policy',
    case when settings->>'attempt_policy' = 'read_only_reentry'
      then 'read_only_reentry' else 'single_resume' end
);
